insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 7, 'Também levou Nabucodonosor à Babilônia dos utensílios da casa do SENHOR, e os pôs no seu templo em Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 8, 'Os demais dos feitos de Jeoaquim, e as abominações que fez, e o que nele se achou, eis que estão escritos no livro dos reis de Israel e de Judá: e reinou em seu lugar Joaquim seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 9, 'De oito anos era Joaquim quando começou a reinar, e reinou três meses e dez dias em Jerusalém: e fez o que era mau aos olhos do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 10, 'Na primavera do ano, o rei Nabucodonosor mandou que o trouxessem à Babilônia, juntamente com os utensílos preciosos da casa do SENHOR; e constituiu o seu irmão Zedequias como rei sobre Judá e Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 11, 'De vinte e um anos era Zedequias quando começou a reinar, e onze anos reinou em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 12, 'E fez o que era mau aos olhos do SENHOR seu Deus, e não se humilhou diante do profeta Jeremias, que lhe falava da parte do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 13, 'Rebelou-se também contra Nabucodonosor, ao qual havia jurado por Deus; e endureceu sua cerviz, e obstinou seu coração, para não voltar-se ao SENHOR o Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 14, 'E também todos os príncipes dos sacerdotes, e o povo, aumentaram a transgressão, seguindo todas as abominações das nações, e contaminando a casa do SENHOR, a qual ele havia santificado em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 15, 'E o SENHOR o Deus de seus pais enviou a eles por meio de seus mensageiros, enviando insistentemente: porque ele tinha misericórdia de seu povo, e de sua habitação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 16, 'Mas eles faziam escárnio dos mensageiros de Deus, e menosprezavam suas palavras, ridicularizando-se de seus profetas, até que subiu o furor do SENHOR contra seu povo, de maneira que não havia remédio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 17, 'Pelo qual trouxe contra eles ao rei dos caldeus, que matou à espada seus rapazes na casa de seu santuário, sem perdoar jovem, nem virgem, nem velho, nem decrépito; todos os entregou em suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 18, 'Também todos os vasos da casa de Deus, grandes e pequenos, os tesouros da casa do SENHOR, e os tesouros do rei e de seus príncipes, tudo o levou à Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 19, 'E queimaram a casa de Deus, e romperam o muro de Jerusalém, e consumiram ao fogo todos seus palácios, e destruíram todos os seus objetos valiosos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 20, 'Os que restaram da espada foram passados à Babilônia; e foram servos dele e de seus filhos, até que veio o reino dos persas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 21, 'Para que se cumprisse a palavra do SENHOR pela boca de Jeremias, até que a terra houvesse aproveitado os seus descansos sabáticos; pois durante todo o tempo de sua ruina ela descansou, até que os setenta anos fossem cumpridos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 22, 'Mas ao primeiro ano de Ciro rei dos persas, para que se cumprisse a palavra do SENHOR por boca de Jeremias, o SENHOR induziu o espírito de Ciro rei dos persas, o qual fez apregoar por todo seu reino, e também por escrito, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 36, 23, 'Assim diz Ciro rei dos persas: o SENHOR, o Deus dos céus, me deu todos os reinos da terra; e ele me encarregou que lhe edifique casa em Jerusalém, que é em Judá. Quem houver de vós de todo seu povo, o SENHOR seu Deus seja com o tal, e suba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 1, 1, 'No primeiro ano de Ciro rei da Pérsia, para que se cumprisse a palavra do SENHOR pela boca de Jeremias, o SENHOR despertou o espírito de Ciro rei da Pérsia, o qual mandou proclamar por todo o seu reino, e também por escrito, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 1, 2, 'Assim diz Ciro, rei da Pérsia: O SENHOR, Deus dos céus, me deu todos os reinos da terra; e ele me mandou que lhe edificasse uma casa em Jerusalém, que está em Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 1, 3, 'Quem há entre vós de todo seu povo, seu Deus seja com ele, e suba a Jerusalém que está em Judá, e edifique a casa ao SENHOR Deus de Israel; ele é o Deus que [habita] em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 1, 4, 'E todo aquele que tiver restado em qualquer lugar onde estiver morando, os homens de seu lugar o ajudem com prata, ouro, bens, e animais; além das doações voluntárias para a casa de Deus, que está em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 1, 5, 'Então se levantaram os chefes das famílias de Judá e de Benjamim, os sacerdotes e os Levitas, e todos [aqueles] cujo espírito Deus despertou, para subirem a edificar a casa do SENHOR, que está em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 1, 6, 'E todos os que estavam em seus arredores fortaleceram suas mãos com objetos de prata e de ouro, com bens e animais, e com coisas preciosas, além de tudo o que foi dado voluntariamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 1, 7, 'Também o rei Ciro tirou os utensílios da casa do SENHOR, que Nabucodonosor tinha trazido de Jerusalém, e posto na casa de seus deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 1, 8, 'E Ciro, rei da Pérsia, tirou-os por meio do tesoureiro Mitridate, o qual os deu contados a Sesbazar, príncipe de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 1, 9, 'E esta é o seu número: trinta bacias de ouro, mil bacias de prata, vinte e nove facas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 1, 10, 'Trinta taças de ouro, quatrocentas e dez taças de prata, e mil outros utensílios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 1, 11, 'Todos os utensílios de ouro e de prata foram cinco mil e quatrocentos. Sesbazar trouxe todos estes com os do cativeiro que subiram da Babilônia a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 1, 'Estes são os filhos da província que subiram do cativeiro, dos transportados que Nabucodonosor, rei de Babilônia, tinha transportado para a Babilônia, e que voltaram a Jerusalém e a Judá, cada um para sua cidade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 2, 'Os quais vieram com Zorobabel, Jesua, Neemias, Seraías, Reelaías, Mardoqueu, Bilsã, Mispar, Bigvai, Reum e Baaná. O registro dos homens do povo de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 3, 'Os filhos de Parós, dois mil cento e setenta e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 4, 'Os filhos de Sefatias, trezentos e setenta e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 5, 'Os filhos de Ara, setecentos e setenta e cinco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 6, 'Os filhos de Paate-Moabe, dos descendentes de Jesua e Joabe, dois mil oitocentos e doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 7, 'Os filhos de Elão, mil duzentos e cinquenta e quatro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 8, 'Os filhos de Zatu, novecentos e quarenta e cinco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 9, 'Os filhos de Zacai, setecentos e sessenta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 10, 'Os filhos de Bani, seiscentos e quarenta e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 11, 'Os filhos de Bebai, seiscentos e vinte e três;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 12, 'Os filhos de Azgade, mil duzentos e vinte e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 13, 'Os filhos de Adonicão, seiscentos e sessenta e seis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 14, 'Os filhos de Bigvai, dois mil e cinquenta e seis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 15, 'Os filhos de Adim, quatrocentos e cinquenta e quatro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 16, 'Os filhos de Ater, de Ezequias, noventa e oito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 17, 'Os filhos de Bezai, trezentos e vinte e três;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 18, 'Os filhos de Jora, cento e doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 19, 'Os filhos de Hasum, duzentos e vinte e três;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 20, 'Os filhos de Gibar, noventa e cinco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 21, 'Os filhos de Belém, cento e vinte e três;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 22, 'Os homens de Netofá, cinquenta e seis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 23, 'Os homens de Anatote, cento e vinte e oito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 24, 'Os filhos de Azmavete, quarenta e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 25, 'Os filhos de Quiriate-Jearim, Quefira, e Beerote, setecentos e quarenta e três;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 26, 'Os filhos de Ramá e Geba, seiscentos e vinte e um;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 27, 'Os homens de Micmás, cento e vinte e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 28, 'Os homens de Betel e Ai, duzentos e vinte e três;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 29, 'Os filhos de Nebo, cinquenta e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 30, 'Os filhos de Magbis, cento e cinquenta e seis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 31, 'Os filhos do outro Elão, mil duzentos e cinquenta e quatro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 32, 'Os filhos de Harim, trezentos e vinte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 33, 'Os filhos de Lode, Hadide, e Ono, setecentos e vinte e cinco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 34, 'Os filhos de de Jericó, trezentos e quarenta e cinco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 35, 'Os filhos de Senaá, três mil seiscentos e trinta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 36, 'Os sacerdotes: os filhos de Jedaías, da casa de Jesua, novecentos e setenta e três;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 37, 'Os filhos de Imer, mil e cinquenta e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 38, 'Os filhos de Pasur, mil duzentos e quarenta e sete;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 39, 'Os filhos de Harim, mil e dezessete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 40, 'Os Levitas: os filhos de Jesua e de Cadmiel, dos filhos de Hodavias, setenta e quatro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 41, 'Os cantores: os filhos de Asafe, cento e vinte e oito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 42, 'Os filhos dos porteiros: os filhos de Salum, os filhos de Ater, os filhos de Talmom, os filhos de Acube, os filhos de Hatita, os filhos de Sobai; ao todo, cento e trinta e nove.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 43, 'Os servos do templo: os filhos de Zia, os filhos de Hasufa, os filhos de Tabaote,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 44, 'Os filhos de Queros, os filhos de Sia, os filhos de Padom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 45, 'Os filhos de Lebana, os filhos de Hagaba, os filhos de Acube;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 46, 'Os filhos de Hagabe, os filhos de Sanlai, os filhos de Hanã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 47, 'Os filhos de Gidel, os filhos de Gaar, os filhos de Reaías;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 48, 'Os filhos de Rezim, os filhos de Necoda, os filhos de Gazão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 49, 'Os filhos de Uzá, os filhos de Paseia, os filhos de Besai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 50, 'Os filhos de Asná, os filhos de Meunim, os filhos de Nefusim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 51, 'Os filhos de Baquebuque, os filhos de Hacufa, os filhos de Harur;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 52, 'Os filhos de Baslute, os filhos de Meída, os filhos de Harsa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 53, 'Os filhos de Barcos, os filhos de Sísera, os filhos de Temá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 54, 'Os filhos de Nesias, os filhos de Hatifa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 55, 'Os filhos dos servos de Salomão: os filhos de Sotai, os filhos de Soferete, os filhos de Peruda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 56, 'Os filhos de Jaala, o filhos de Darcom, os filhos de Gidel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 57, 'Os filhos de Sefatias, os filhos de Hatil, os filhos de Poquerete-Hazebaim, os filhos de Ami.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 58, 'Todos os servos do templo, e filhos dos servos de Salomão, trezentos e noventa e dois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 59, 'Também estes subiram de Tel-Melá, Tel-Harsa, Querube, Adã, e Imer, porém não puderam mostrar a família de seus pais, nem sua linhagem, se eram de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 60, 'Os filhos de Delaías, os filhos de Tobias, os filhos de Necoda, seiscentos e cinquenta e dois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 61, 'E dos filhos dos sacerdotes: os filhos de Habaías, os filhos de Coz, os filhos de Barzilai, o qual tomou mulher das filhas de Barzilai gileadita, e foi chamado pelo nome delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 62, 'Estes buscaram seu registro de genealogias, mas não foi achado; por isso foram rejeitados do sacerdócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 63, 'E o governador lhes mandou que não comessem das coisas sagradas, até que houvesse sacerdote com Urim e Tumim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 64, 'Toda esta congregação junta foi quarenta e dois mil trezentos e sessenta,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 65, 'Sem seus servos e servas, os quais foram sete mil trezentos trinta e sete; também tinham duzentos cantores e cantoras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 66, 'Seus cavalos foram setecentos e trinta e seis; seus mulos, duzentos e quarenta e cinco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 67, 'Seus camelos, quatrocentos trinta e cinco; asnos, seis mil setecentos e vinte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 68, 'E [alguns] dos chefes de famílias, quando vieram à casa do SENHOR que estava em Jerusalém, deram ofertas voluntárias para a casa de Deus, para [a] reconstruírem em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 69, 'Conforme sua capacidade deram ao tesouro da obra sessenta e uma mil dracmas de ouro, cinco mil libras de prata, e cem vestes sacerdotais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 2, 70, 'E os sacerdotes, os Levitas, os do povo, os cantores, os porteiros e os servos do templo, habitaram em suas cidades; como também todo Israel em suas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 3, 1, 'Tendo, pois, chegado o mês sétimo, e já estando os filhos de Israel nas cidades, o povo se ajuntou como um só homem em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 3, 2, 'E levantaram-se Jesua, filho de Jozadaque, e seus irmãos os sacerdotes, e Zorobabel filho de Sealtiel, e seus irmãos, e edificaram o altar do Deus de Israel, para oferecerem sobre ele ofertas de queima, como está escrito na Lei de Moisés, homem de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 3, 3, 'E assentaram o altar sobre suas bases, porém com medo sobre si, por causa dos povos das terras; e ofereceram sobre ele ofertas de queima ao SENHOR, ofertas de queima à manhã e à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 3, 4, 'E celebraram a festa dos tabernáculos, como está escrito; fizeram ofertas de queima diariamente conforme a regra exigida a cada dia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 3, 5, 'E depois disto, ofereceram o holocausto contínuo, assim como os as das luas novas, e todas as festas santificadas ao SENHOR, como também de qualquer um que dava oferta voluntária ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 3, 6, 'Desde o primeiro dia do mês sétimo começaram a oferecer holocaustos ao SENHOR; porém ainda não estavam postos os fundamentos do templo do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 3, 7, 'Assim deram dinheiro aos pedreiros e carpinteiros; como também comida, bebida, e azeite aos sidônios e aos tírios, para que trazerem do Líbano madeira de cedro ao mar de Jope, conforme a autorização de Ciro, rei da Pérsia, acerca disto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 3, 8, 'E no ano segundo de sua vinda à casa de Deus em Jerusalém, no mês segundo, começaram Zorobabel, filho de Sealtiel, Jesua, filho de Jozadaque, com os outros irmãos seus, os sacerdotes e os levitas, e todos os que haviam vindo do cativeiro a Jerusalém. E ordenaram aos levitas da idade de vinte anos acima, que cuidassem da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 3, 9, 'Então Jesua, seus filhos e seus irmãos, Cadmiel e seus filhos, filhos de Judá, se levantaram como um só homem para supervisionarem os que faziam a obra na casa de Deus; [com] os filhos de Henadade, seus filhos e seus irmãos, levitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 3, 10, 'E quando os construtores do templo do SENHOR puseram os fundamentos, então ordenaram aos sacerdotes, já com as vestimentas e com trombetas, e aos levitas filhos de Asafe com címbalos, para louvarem ao SENHOR, conforme a ordenança de Davi, rei de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 3, 11, 'E cantavam em revezamento, louvando e celebrando ao SENHOR:Porque ele é bom, porque sua bondade sobre Israel dura para sempre!E todo o povo gritava com grande júbilo, louvando ao SENHOR, por causa da fundação da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 3, 12, 'Porém muitos dos sacerdotes e dos levitas e dos chefes de famílias, já velhos, que haviam visto a primeira casa, quando viram a fundação desta casa, choravam em alta voz, mas muitos outros davam grandes gritos de alegria;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 3, 13, 'De maneira que o povo não conseguia distinguir as vozes de alegria das vozes de choro do povo; porque o povo gritava com tão grande júbilo, que se podia ouvir o som de muito longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 1, 'Quando, pois, os adversários de Judá e de Benjamim, ouviram que os que tinham vindo do cativeiro estavam edificando o templo ao SENHOR, Deus de Israel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 2, 'chegaram-se a Zorobabel, e aos chefes das famílias, e lhes disseram: Deixai-nos edificar convosco, porque assim como vós, buscaremos ao vosso Deus, como também já sacrificamos a ele desde os dias de Esar-Hadom, rei da Assíria, que nos fez subir até aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 3, 'Porém Zorobabel, Jesua, e os demais chefes das famílias de Israel lhes disseram: Não nos convém edificar convosco casa a nosso Deus; mas somente nós a edificaremos ao SENHOR, Deus de Israel, como nos mandou o rei Ciro, rei da Pérsia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 4, 'Todavia o povo da terra desencorajava o povo de Judá, e os perturbava, para que não edificassem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 5, 'E subornaram contra eles conselheiros para frustrarem sua intenção, todos os dias de Ciro rei da Pérsia, e até o reinado de Dario, rei da Pérsia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 6, 'E sob o reinado de Assuero, no princípio de seu reinado, escreveram uma acusação contra os moradores de Judá e de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 7, 'E nos dias de Artaxerxes, Bislão, Mitridate, Tabeel, e os demais seus companheiros, escreveram a Artaxerxes rei da Pérsia; e o escrito da carta estava feito em siríaco, e composto em siríaco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 8, 'Reum o comandante, e Sinsai o escrivão, escreveram uma carta contra Jerusalém ao rei Artaxerxes, conforme o seguinte:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 9, 'Reum, o comandante, e Sinsai secretário, e os demais seus companheiros, os dinaítas, os arfasaquitas, tarpelitas, arfasitas, os arquevitas, os babilônios, susanquitas, deavitas, e elamitas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 10, 'E os demais povos que o grande e famoso Asnapar transportou, e fez habitar nas cidades de Samaria, e os demais da região dalém do rio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 11, 'Este é o teor da carta que enviaram: Ao rei Artaxerxes. De teus servos dalém do rio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 12, 'Seja conhecido do rei que os judeus que subiram de ti a nós, vieram a Jerusalém; e edificam aquela cidade rebelde e má, e estão restaurando [seus] muros; e reparado [seus] fundamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 13, 'Seja agora conhecido do rei, que se aquela cidade for reconstruída, e os muros forem restaurados, os tributos, taxas, e impostos não serão pagos, e o patrimônio real será prejudicado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 14, 'Visto que somos assalariados pelo palácio, não nos convém ver a desonra do rei; por isso mandamos informar ao rei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 15, 'Para que se busque no livro das crônicas de teus pais; e acharás no livro das crônicas, e saberás que aquela cidade foi uma cidade rebelde, prejudicial aos reis e às províncias, e que nela desde antigamente fizeram rebeliões; por isso aquela cidade foi arruinada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 16, 'Por isso informamos ao rei que, se aquela cidade for reconstruída, e seus muros restaurados, a parte além do rio não será tua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 17, '[Então] o rei enviou [esta] resposta a Reum, o comandante, e a Sinsai, o escrivão, e aos demais de seus companheiros que habitam em Samaria, como também aos demais da parte além do rio: Paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 18, 'A carta que nos enviastes foi lida claramente diante de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 19, 'E eu dei ordem para que se buscasse; e encontraram que aquela cidade na antiguidade se levantou contra os reis, e nela houve rebelião e insurreição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 20, 'E que houve reis poderosos em Jerusalém, dominaram toda a região além do rio; e a eles se pagava tributos, taxas e impostos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 21, 'Agora, pois, dai ordem que impeçam aqueles homens, e aquela cidade não seja reconstruída, até que seja dado mandamento de minha parte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 22, 'E sede cuidadosos para que não falheis nisto; por que haveria de aumentar o dano para o prejuízo real?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 23, 'Assim que o teor da carta do rei Artaxerxes foi lido diante de Reum, e de Sinsai o escrivão, e seus companheiros, eles foram apressadamente a Jerusalém aos judeus, e os impediram com força e violência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 4, 24, 'Cessou, então, a obra da casa de Deus, a qual estava em Jerusalém; e cessou até o segundo ano do reinado de Dario, rei da Pérsia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 1, 'E o profeta Ageu, e Zacarias filho de Ido, profetas, profetizaram aos judeus que estavam em Judá e em Jerusalém, em nome do Deus de Israel, a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 2, 'Então se levantaram Zorobabel, filho de Sealtiel, e Jesua, filho de Jozadaque; e começaram a reconstruir a casa de Deus que está em Jerusalém; e com eles os profetas de Deus, que os ajudavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 3, 'Naquele tempo veio a eles Tatenai, capitão da região além do rio, e Setar-Bozenai e seus companheiros, e lhes perguntaram assim:Quem vos deu ordem para reconstruir esta casa, e restaurar estes muros?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 4, 'Então assim lhes dissemos quais eram os nomes dos homens que reconstruíam este edifício.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 5, 'Mas os olhos de seu Deus estavam sobre os anciãos dos judeus, e não os impediram, até que a causa viesse a Dario; e então responderam por carta sobre isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 6, 'Teor da carta que Tatenai, o governador além do rio, e Setar-Bozenai, e seus companheiros os afarsaquitas, que estavam além do rio, enviaram ao rei Dario.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 7, 'Enviaram-lhe uma carta, e assim estava escrito nela: Toda a paz ao rei Dario.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 8, 'Seja conhecido do rei, que fomos à província de Judeia, à casa do grande Deus, a qual é edificada com grandes pedras; e a madeira é posta nas paredes, e a obra se faz apressadamente, e tem sido próspera a em suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 9, 'Então perguntamos aos anciãos, dizendo-lhes assim: Quem vos deu ordem para reconstruir esta casa, e para restaurar estes muros?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 10, 'E também lhes perguntamos seus nomes para os informar a ti; para que pudéssemos escrever a ti os nomes dos homens que eram os seus líderes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 11, 'E nos deram esta resposta, dizendo: Nós somos servos de Deus do céu e da terra, e reconstruímos a casa que a muitos anos antes tinha sido construída, a qual um grande rei de Israel iniciou e terminou de construir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 12, 'Mas depois que nossos pais provocaram à ira o Deus dos céus, ele os entregou nas mãos de Nabucodonosor, rei de Babilônia, o caldeu, o qual destruiu esta casa, e transportou o povo para a Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 13, 'Porém no primeiro ano de Ciro, rei da Babilônia, o rei Ciro fez um decreto para reconstruir esta casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 14, 'E até os utensílios de ouro e de prata da casa de Deus, que Nabucodonosor tinha tomado do templo que estava em Jerusalém, e os tinha posto no templo da Babilônia, o rei Ciro os tirou do templo da Babilônia, e foram entregues a um chamado Sesbazar, a quem pusera por governador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 15, 'E disse-lhe: Toma estes utensílios, vai, [e] põe-os no templo que está em Jerusalém; e seja reconstruída a casa de Deus em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 16, 'Então este Sesbazar veio, e pôs os fundamentos da casa de Deus, que está em Jerusalém, e desde então até agora foi reconstruída, e ainda não foi terminada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 5, 17, 'Agora, pois, se for do agrado do rei, busque-se na casa dos tesouros do rei que está ali na Babilônia, se é [verdade] que rei Ciro foi feito decreto para reconstruir esta casa de Deus em Jerusalém, e seja nos enviada a vontade do rei acerca disto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 1, 'Então o rei Dario deu ordem, e buscaram nos arquivos da tesouraria na Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 2, 'E foi achado em Ecbatana, no palácio que está na província de Média, um livro, dentro do qual estava escrito assim: Memórial:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 3, 'No primeiro ano do rei Ciro, o rei Ciro fez decreto acerca da casa de Deus que estava em Jerusalém, que fosse reconstruído a casa, o lugar em que sejam oferecidos sacrifícios, e que suas paredes sejam cobertas; sua altura será de sessenta côvados, e sua largura de sessenta côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 4, 'Com três camadas de grandes pedras, e uma camada de madeira nova e que o gasto seja dado da casa do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 5, 'Além disso, os utensílios de ouro e de prata da casa de Deus, que Nabucodonosor tirou do templo que estava em Jerusalém e levou a Babilônia, sejam devolvidos para irem ao templo que está em Jerusalém, a seu lugar, e sejam postos na casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 6, 'Agora, [pois] , Tatenai, chefe dalém rio, Setar-Bozenai, e seus companheiros os afarsaquitas que estais além do rio, afastai-vos dali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 7, 'Deixai-os na obra da casa de Deus; que o governador dos judeus, e os anciãos dos judeus, edifiquem esta casa deste Deus em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 8, 'Também por mim é promulgado decreto do que haveis de fazer com os anciãos destes judeus, para edificar a casa deste Deus: que do patrimônio do rei, dos tributos dalém do rio, sejam pagos os gastos destes homens varões, para que [a obra] não seja interrompida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 9, 'E o que for necessário, como bezerros, carneiros e cordeiros, para holocaustos ao Deus do céu, trigo, sal, vinho e azeite, conforme o que os sacerdotes que estão em Jerusalém disserem, seja lhes dado a cada um sem falta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 10, 'Para que ofereçam sacrifícios de aroma suave ao ao Deus dos céus, e orem pela vida do rei e de seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 11, 'Também é dada por mim ordem, que qualquer um que mudar este decreto, um madeiro de sua casa seja derrubado, levantado, e nele seja empalado; e sua casa se torne um amontoado por causa disso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 12, 'E o Deus que fez habitar ali seu nome, derrube a todo rei e povo que estenderem sua mão para mudar ou destruir esta casa de Deus, que está em Jerusalém. Eu, Dario, fiz o decreto; apressadamente se cumpra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 13, 'Então Tatenai, o governador dalém do rio, e Setar-Bozenai, e seus companheiros, assim fizeram apressadamente, conforme o que o rei Dario havia mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 14, 'E os anciãos dos judeus iam edificando e prosperando, pela profecia do profeta Ageu, e de Zacarias filho de Ido. E edificaram, e terminaram a construção conforme o mandamento do Deus de Israel, e conforme o mandamento de Ciro e de Dario, e de Artaxerxes rei da Pérsia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 15, 'E esta casa foi terminada ao terceiro dia do mês de Adar, que era o sexto ano do reinado do rei Dario.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 16, 'E os filhos de Israel, os sacerdotes e os levitas, e os demais dos que vieram do cativeiro, fizeram a consagração desta casa de Deus com alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 17, 'E ofereceram para a consagração desta casa de Deus cem novilhos, duzentos carneiros, quatrocentos cordeiros; e doze cabritos por expiação do pecado de todo Israel, segundo o número das tribos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 18, 'E puseram aos sacerdotes em suas divisões, e aos levitas em seus grupos, para o serviço a Deus, que está em Jerusalém, conforme o que está escrito no livro de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 19, 'E os que vieram do cativeiro celebraram a páscoa aos catorze do mês primeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 20, 'Porque os sacerdotes e os levitas haviam se purificado juntos; todos foram limpos; e fizeram o sacrifício da páscoa por todos os que vieram do cativeiro, e por seus irmãos, os sacerdotes, e por si mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 21, 'Assim os filhos de Israel que haviam voltado do cativeiro comeram, com todos os que tinham se separado da impureza das nações da terra, para buscarem ao SENHOR Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 6, 22, 'E celebraram a festa dos pães sem fermento sete dias com alegria, porque o SENHOR os tinha alegrado, e convertido o coração do rei da Assíria a eles, para fortalecer suas mãos na obra da casa de Deus, o Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 1, 'Passadas estas coisas, no reinado de Artaxerxes, rei da Pérsia, Esdras, filho de Seraías, filho de Azarias, filho de Hilquias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 2, 'filho de Salum, filho de Zadoque, filho de Aitube,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 3, 'filho de Amarias, filho de Azarias, filho de Meraiote,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 4, 'filho de Zeraías, filho de Uzi, filho de Buqui,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 5, 'filho de Abisua, filho de Fineias, filho de Eleazar, filho de Arão, o sumo sacerdote;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 6, 'este Esdras subiu da Babilônia; e ele era escriba habilidoso na lei de Moisés, dada pelo SENHOR Deus de Israel; e segundo a mão do SENHOR, seu Deus, sobre ele, o rei lhe deu tudo quanto lhe pedira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 7, 'E subiram com ele a Jerusalém [alguns] dos filhos de Israel, dos sacerdotes, levitas, cantores, porteiros, e servos do templo, no sétimo ano do rei Artaxerxes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 8, 'E ele chegou a Jerusalém no mês quinto, no sétimo ano do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 9, 'Pois no primeiro [dia] do mês primeiro, foi o princípio da subida da Babilônia; e ao primeiro do mês quinto chegou a Jerusalém, segundo a boa mão de seu Deus sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 10, 'Porque Esdras tinha decidido em seu coração buscar a lei do SENHOR, e a praticar; e ensinar a Israel [seus] estatutos e juízos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 11, 'E este é a transcrição da carta que o rei Artaxerxes deu a Esdras, sacerdote e escriba, o escriba das palavras dos mandamentos do SENHOR, e de seus estatutos sobre Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 12, 'Artaxerxes, rei de reis, ao sacerdote Esdras, escriba da Lei de Deus do céu. [Paz] completa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 13, 'Por mim é promulgado decreto, que todo aquele em meu reino, do povo de Israel, e de seus sacerdotes e levitas, que quiser ir contigo a Jerusalém, vá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 14, 'Porque de parte do rei e de seus sete conselheiros tu és enviado a investigar a respeito da de Judá e de Jerusalém, conforme a lei de teu Deus que está em tua mão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 15, 'E a levar a prata e o ouro que o rei e seus conselheiros voluntariamente deram ao Deus de Israel, cuja habitação está em Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 16, 'E também toda a prata e o ouro que achares em toda a província de Babilônia, com as ofertas voluntárias do povo e dos sacerdotes, que voluntariamente oferecerem para a casa de seu Deus que está em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 17, 'Portanto, com este dinheiro, compra novilhos, carneiros, cordeiros, com seus suas ofertas de alimento e suas ofertas de bebidas, e oferece-os sobre o altar da casa de vosso Deus, que está em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 18, 'Também o que a ti e a teus irmãos parecer bem fazerdes do restante da prata e do ouro, fazei [-o] conforme a vontade de vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 19, 'E os utensílios que te foram entregues para o serviço da casa de teu Deus, restitui-os diante do Deus de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 20, 'E o demais que for necessário para a casa de teu Deus que caiba a ti dar, tu o darás da casa dos tesouros do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 21, 'E por mim mesmo, o rei Artaxerxes, é dado decreto a todos os tesoureiros que estão além do rio, que tudo quanto o sacerdote Esdras, escriba da lei do Deus dos céus, vos pedir, apressadamente lhe seja concedido;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 22, 'Até cem talentos de prata, e até cem coros de trigo, e até cem batos de vinho, e até cem batos de azeite; e sal sem limite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 23, 'Tudo o que for ordenado pelo Deus do céu, prontamente se faça para a casa do Deus do céu; pois para que teria de haver grande ira contra o reino do rei e de seus filhos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 24, 'Também vos fazemos saber, acerca de todos os sacerdotes, levitas, cantores, porteiros, servos do templo, e trabalhadores da casa de Deus, ninguém possa lhes impor tributo, imposto, ou taxa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 25, 'E tu, Esdras, conforme a sabedoria de teu Deus que está contigo, põe oficiais e juízes, que julguem a todo o povo que está além do rio, a todos os que conhecem as Leis de teu Deus; e ao que não as conhecerem, tu lhes ensinará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 26, 'E todo aquele que não cumprir a Lei de teu Deus e a lei do rei, prontamente seja julgado, ou à morte, ou à expulsão, ou à multa, ou à prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 27, 'Bendito seja o SENHOR, Deus de nossos pais, que pôs tal coisa no coração do rei, para glorificar a casa do SENHOR, que está em Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 7, 28, 'E sobre mim inclinou bondade diante do rei e de seus conselheiros, e de todos os príncipes poderosos do rei. Assim eu me esforcei segundo a mão do SENHOR meu Deus sobre mim, e ajuntei os líderes de Israel para subirem comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 1, 'Estes, pois, são os chefes de suas famílias, com suas genealogias, dos que subiram comigo da Babilônia durante o reinando do rei Artaxerxes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 2, 'Dos filhos de Fineias, Gérson; dos filhos de Itamar, Daniel; dos filhos de Davi, Hatus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 3, 'Dos filhos de Secanias e dos filhos de Parós, Zacarias, e com ele por genealogias foram contados cento e cinquenta homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 4, 'Dos filhos de Paate-Moabe, Elioenai, filho de Zeraías, e com ele duzentos homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 5, 'Dos filhos de Secanias, o filho de Jaaziel, e com ele trezentos homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 6, 'Dos filhos de Adim, Ebede, filho de Jônatas, e com ele cinquenta homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 7, 'Dos filhos de Elão, Jesaías, filho de Atalias, e com ele setenta homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 8, 'E dos filhos de Sefatias, Zebadias, filho de Micael, e com ele oitenta homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 9, 'Dos filhos de Joabe, Obadias, filho de Jeiel, e com ele duzentos e dezoito homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 10, 'E dos filhos de Selomite, o filho de Josifias, e com ele cento e sessenta homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 11, 'E dos filhos de Bebai, Zacarias, filho de Bebai, e com ele vinte e oito homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 12, 'E dos filhos de Azgade, Joanã, filho de Catã, e com ele cento e dez homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 13, 'E dos filhos de Adonicão, os últimos, cujos nomes são: Elifelete, Jeiel, e Semaías, e com eles sessenta homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 14, 'E dos filhos de Bigvai, Utai e Zabude, e com eles setenta homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 15, 'E ajuntei-os junto ao rio que vai a Aava, e acampamos ali três dias; então procurem entre o povo e entre os sacerdotes, não achei ali nenhum dos filhos de Levi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 16, 'Por isso enviei a Eliezer, Ariel, Semaías, Elnatã, Jaribe, Elnatã, Natã, Zacarias, e a Mesulão, os chefes; como também a Joiaribe e a Elnatã, os sábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 17, 'E os enviei a Ido, chefe no lugar de Casifia; e lhes instruí as palavras que deviam dizer a Ido, e a seus irmãos, os servos do templo no lugar de Casifia, para que nos trouxessem trabalhadores para a casa de nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 18, 'E nos trouxeram, segundo a boa mão de nosso Deus sobre nós, um homem entendido dos filhos de Mali, filho de Levi, filho de Israel; [cujo nome era] Serebias com seus filhos e seus irmãos, dezoito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 19, 'E a Hasabias, e com ele a Jesaías dos filhos de Merari, seus irmãos e a seus filhos, vinte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 20, 'E dos servos do templo, a quem Davi e os príncipes puseram para o trabalho dos Levitas, duzentos e vinte servos do templo; todos eles foram indicados por nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 21, 'Então proclamei ali um jejum junto ao rio de Aava, para nos humilharmos diante de nosso Deus, para lhe pedirmos um caminho seguro para nós, nossos filhos, e todos os nossos bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 22, 'Pois tive vergonha de pedir ao rei tropas e cavaleiros para nos defenderem do inimigo no caminho; porque tínhamos falado ao rei, dizendo: A mão de nosso Deus está para o bem sobre todos os que o buscam; mas sua força e ira está sobre todos os que o abandonam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 23, 'Assim jejuamos, e pedimos isto a nosso Deus; e ele atendeu a nossas orações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 24, 'Então separei doze dos chefes dos sacerdotes, a Serebias e Hasabias, e com eles dez de seus irmãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 25, 'E pesei-lhes a prata, o ouro, e os utensílios, [que] eram a oferta para a casa de nosso Deus que o rei, seus conselheiros, seus príncipes, e todo os israelitas que se acharam, haviam oferecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 26, 'Assim pesei nas mãos deles seiscentos e cinquenta talentos de prata, e cem talentos de utensílios de prata, e cem talentos de ouro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 27, 'E vinte bacias de ouro, de mil dracmas; e dois vasos bronze reluzente, tão preciosos como o ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 28, 'E disse-lhes: Vós sois consagrados ao SENHOR, e estes utensílios são santos; como também a prata e o ouro, [que são] oferta voluntária ao SENHOR, Deus de vossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 29, 'Vigiai, e guardai [estas coisas] , até que as peseis diante dos líderes dos sacerdotes e dos levitas, e dos chefes das famílias de Israel em Jerusalém, nas câmaras da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 30, 'Então os sacerdotes e os levitas receberam o peso da prata e do ouro e dos utensílios, para o trazerem a Jerusalém, à casa de nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 31, 'Assim nos partimos do rio de Aava, ao [dia] doze do mês primeiro, para irmos a Jerusalém; e a mão do nosso Deus estava sobre nós, e nos livrou de mão de inimigos e dos assaltantes no caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 32, 'E chegamos a Jerusalém, e repousamos ali três dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 33, 'Ao quarto dia foram pesados a prata, o ouro, e os utensílios, na casa de nosso Deus, por meio de Meremote, filho do sacerdote Urias, e com ele Eleazar, filho de Fineias; e com eles os levitas: Jozabade, filho de Jesua, e Noadias, filho de Binui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 34, 'Tudo foi [conferido] em número e em peso; e ao mesmo tempo o peso foi registrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 35, 'E os transportados, os que vieram do cativeiro, deram como oferta de queima ao Deus de Israel doze novilhos por todos os israelitas, noventa e seis carneiros, setenta e sete cordeiros, e doze bodes como sacrifício pelo pecado; tudo [isto] como oferta de queima ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 8, 36, 'Então deram as ordens do rei aos comissários do rei, e aos governadores dalém do rio, os quais ajudaram ao povo e à casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 1, 'Acabadas, pois, estas coisas, os príncipes se achegaram a mim, dizendo: O povo de Israel, os sacerdotes e os levitas, não têm se separado dos povos destas terras, segundo suas abominações: dos cananeus, heteus, perizeus, jebuseus, amonitas, moabitas, egípcios, e amorreus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 2, 'Pois tomaram de suas filhas para si e para seus filhos, e [assim] a descendência santa se misturou com os povos destas terras; e os príncipes e os oficiais foram os primeiros nesta transgressão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 3, 'Quando eu ouvi isto, rasguei a minha roupa e meu manto; e arranquei dos cabelos de minha cabeça e de minha barba, e me sentei atônito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 4, 'Então se juntaram a mim todos os que se tremiam pelas palavras do Deus de Israel, por causa da transgressão dos que eram do cativeiro; mas eu fiquei sentado, atônito, até o sacrifício da tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 5, 'E perto do sacrifício da tarde eu me levantei de minha aflição; e já tendo rasgado minha roupa e meu manto, inclinei-me de joelhos, e estendi minhas mãos ao SENHOR meu Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 6, 'E disse: Meu Deus, estou confuso e envergonhado de levantar a ti, meu Deus, o meu rosto; pois nossas perversidades se multiplicaram sobre nossa [cabeça] , e nossa culpa cresceu até os céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 7, 'Desde os dias de nossos pais até o dia de hoje estamos em grande culpa; e por nossas perversidades nós, nossos reis, e nossos sacerdotes, somos entregues nas mãos dos reis das terras, à espada, ao cativeiro, ao roubo, e à vergonha de rosto, como [se vê] hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 8, 'Mas agora, por um breve momento, houve favor da parte do SENHOR nosso Deus, para deixar um restante livre, e para nos dar uma estaca em seu santo lugar, a fim de iluminar nossos olhos, ó Deus nosso, e nos dar um pouco de alívio em nossa escravidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 9, 'Porque somos escravos; porém em nossa escravidão nosso Deus não nos desamparou, mas, sim, inclinou sobre nós bondade diante dos reis da Pérsia, para nos dar alívio, para levantarmos a casa de nosso Deus, e restaurarmos suas ruínas, e para nos dar um muro em Judá e em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 10, 'Mas agora, ó Deus nosso, o que diremos depois disto? Porque abandonamos os teus mandamentos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 11, 'Os quais mandaste por meio de teus servos, os profetas, dizendo: A terra em que entrais para tomar posse é um terra imunda, por causa das imundícias dos povos daquelas terras, por suas abominações com que a encheram de um extremo ao outro de sua contaminação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 12, 'Agora, pois, não dareis vossas filhas aos seus filhos, nem tomareis suas filhas para vossos filhos, e nunca procurareis sua paz nem seu bem; para que vos fortaleçais, e comais o bem da terra, e a deixeis por herança a vossos filhos para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 13, 'E depois de tudo o que nos sobreveio por causa de nossas más obras, e de nossa grande culpa, ainda que tu, Deus nosso, puniste menos do que [merecíamos] por nossas perversidades, e nos deixaste um remanescente como este;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 14, 'Voltaremos, pois, agora, a anular teus mandamentos, e a nos aparentarmos com os povos destas abominações? Não te indignarias tu contra nós até nos consumir, até não haver resto nem remanescente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 9, 15, 'Ó SENHOR, Deus de Israel, tu és justo; pois restamos como remanescente, assim como [se vê] hoje. Eis que estamos diante de ti em nossa culpa; ainda que por causa disso ninguém há que possa subsistir diante de tua presença.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 1, 'E enquanto Esdras estava orando, confessando, chorando, e prostrando-se diante da casa de Deus, ajuntou-se a ele uma multidão muito grande de israelitas, homens, mulheres, e crianças; pois o povo chorava muito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 2, 'Então Secanias, filho de Jeiel, dos filhos de Elão, respondeu a Esdras, dizendo: Nós temos transgredido contra nosso Deus, pois nos casamos com mulheres estrangeiras dos povos da terra; mas quanto a isto, ainda há esperança para Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 3, 'Agora, pois, façamos um pacto com o nosso Deus, de que despediremos todas as mulheres e os todos os nascidos delas, conforme o conselho do Senhor, e dos que tremem ao mandamento de nosso Deus; e faça-se conforme à lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 4, 'Levanta-te, porque cabe a ti este negócio, e nós seremos contigo; esforça-te, e age.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 5, 'Então Esdras se levantou, e fez os chefes dos sacerdotes e dos levitas, e a todo Israel, jurarem que fariam conforme essa palavra; e eles juraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 6, 'E Esdras se levantou de diante da casa de Deus, e entrou na câmara de Joanã, filho de Eliasibe; e depois de chegar lá, não comeu pão nem bebeu água, porque estava entristecido pela transgressão dos que eram do cativeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 7, 'Então proclamaram em Judá e em Jerusalém a todos os que vieram do cativeiro, que se reunissem em Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 8, 'E que de todo aquele que não viesse em três dias, segundo o conselho dos príncipes e dos anciãos, fosse tomada toda a sua riqueza, e ele fosse separado da comunidade dos do cativeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 9, 'Então todos os homens de Judá e de Benjamim se reuniram em Jerusalém em três dias, aos vinte do mês, no nono mês; e todo o povo se sentou na praça da casa de Deus, tremendo por causa deste negócio, e por causa das grandes chuvas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 10, 'Assim o sacerdote Esdras se levantou, e lhes disse: Vós transgredistes, por terdes se casado com mulheres estrangeiras, aumentando assim a culpa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 11, 'Agora, pois, confessai ao SENHOR, Deus de vossos pais, e fazei a sua vontade, e separai-vos dos povos das terras, e das mulheres estrangeiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 12, 'E toda a congregação respondeu, dizendo em alta voz: Assim se faça, conforme a tua palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 13, 'Porém o povo é muito, e o tempo chuvoso, e não há condições de ficar fora das casas; nem esta obra é de um dia ou de dois, porque somos muitos os que transgredimos neste negócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 14, 'Portanto fiquem encarregados nossos príncipes por toda a congregação; e todos os que em nossas cidades que houverem se casado com mulheres estrangeiras, venham a tempos determinados, e com eles os anciãos de cada cidade, e seus juízes, até que desviemos de nós o ardor da ira de nosso Deus por esta causa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 15, 'Somente Jônatas, filho de Asael, e Jazeias, filho de Ticvá, apoiados por Mesulão e o levita Sabetai, se opuseram a isso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 16, 'E assim fizeram os que vieram do cativeiro; e foram separados pelo sacerdote Esdras os homens, chefes de famílias, segundo a casa de seus pais, todos eles por nomes, para se sentarem ao dia primeiro do mês décimo, para investigarem este negócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 17, 'E ao primeiro dia do mês primeiro, terminaram [de investigar] os homens que haviam se casado com mulheres estrangeiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 18, 'E dos filhos dos sacerdotes que haviam se casado com mulheres estrangeiras, foram achados estes: dos filhos de Jesua, filho de Jozadaque, e de seus irmãos: Maaseias, Eliézer, Jaribe, e Gedalias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 19, 'E prometeram despedir suas mulheres e, reconhecendo sua culpa, ofereceram um carneiro do rebanho pela transgressão deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 20, 'E dos filhos de Imer: Hanani e Zebadias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 21, 'E do filhos de Harim, Maaseias, Elias, Semaías, Jeiel, e Uzias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 22, 'E dos filhos de Pasur: Elioenai, Maaseias, Ismael, Natanael, Jozabade, e Elasá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 23, 'E dos filhos dos levitas: Jozabade, Simei, Quelaías (este é Quelita), Petaías, Judá, e Eliézer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 24, 'E dos cantores: Eliasibe; e dos porteiros: Salum, Telém, e Uri.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 25, 'E dos [demais] israelitas: Dos filhos de Parós: Ramias, Jezias, Malquias, Miamim, Eleazar, e Malquias, e Benaías.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 26, 'E dos filhos de Elão: Matanias, Zacarias, Jeiel, Abdi, Jeremote, Elias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 27, 'E dos filhos de Zatu: Elioenai, Eliasibe, Matanias, e Jeremote, Zabade, e Aziza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 28, 'E dos filhos de Bebai: Jeoanã, Hananias, Zabai, Atlai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 29, 'E dos filhos de Bani: Mesulão, Maluque, Adaías, Jasube, Seal, e Jeremote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 30, 'E dos filhos de Paate-Moabe: Adna, Quelal, Benaías, Maaseias, Matanias, Bezalel, Binui e Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 31, 'E dos filhos de Harim: Eliézer, Issias, Malquias, Semaías, Simeão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 32, 'Benjamim, Maluque, e Semarias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 33, 'Dos filhos de Hasum: Matenai, Matatá, Zabade, Elifelete, Jeremai, Manassés, Simei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 34, 'Dos filhos de Bani: Maadai, Anrão, Uel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 35, 'Benaías, Bedias, Queluí,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 36, 'Vanias, Meremote, Eliasibe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 37, 'Matanias, Matenai, e Jaasai,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 38, 'E Bani, e Binui, Simei,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 39, 'Selemias, Natã, Adaías,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 40, 'Macnadbai, Sasai, Sarai,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 41, 'Azareel, Selemias, Semarias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 42, 'Salum, Amarias, José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 43, 'E dos filhos de Nebo: Jeiel, Matitias, Zabade, Zebina, Jadai, Joel, e Benaías.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 15, 'Esdras', 'Ed', 10, 44, 'Todos estes haviam tomado mulheres estrangeiras; e [alguns] deles tiveram filhos com tais mulheres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 1, 1, 'Palavras de Neemias, filho de Hacalias.E aconteceu no mês de Quisleu, no ano vigésimo, enquanto eu estava na fortaleza de Susã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 1, 2, 'Veio Hanani, um de meus irmãos, ele e [alguns] homens de Judá, e perguntei-lhes pelos judeus que haviam escapado, que restaram do cativeiro, e por Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 1, 3, 'E me disseram: Os remanescentes, os que restaram do cativeiro lá na província, estão em grande miséria e desprezo; e o muro de Jerusalém está fendido, e suas portas queimadas a fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 1, 4, 'E aconteceu que, quando eu ouvi estas palavras, sentei-me e chorei, e fiquei de luto por [alguns] dias; e jejuei e orei diante do Deus dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 1, 5, 'E disse: Ó SENHOR, Deus dos céus, Deus grande e temível, que guarda o pacto e a bondade aos que o amam e guardam seus mandamentos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 1, 6, 'Estejam, pois, os teus ouvidos atentos, e teus olhos abertos, para ouvires a oração de teu servo, que eu oro hoje diante de ti dia e noite, pelos filhos de Israel, teus servos; e confesso os pecados dos filhos de Israel que pecamos contra ti; também eu e a casa de meu pai pecamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 1, 7, 'Agimos muito corruptamente contra ti, e não guardamos os mandamentos, nem o estatutos nem os juízos, que mandaste ao teu servo Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 1, 8, 'Lembra-te, pois, da palavra que mandaste a teu servo Moisés, dizendo: [Se] vós transgredirdes, eu vos dispersarei entre os povos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 1, 9, 'Mas [se] vos converterdes a mim, e guardardes meus mandamentos, e os praticardes; então ainda que os rejeitados estejam nos confins dos céus, de lá eu os ajuntarei, e os trarei ao lugar que escolhi para fazer habitar ali o meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 1, 10, 'Eles são teus servos e teu povo, que resgataste com teu grande poder, e com tua mão forte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 1, 11, 'Por favor, SENHOR, estejam teus ouvidos atentos à oração do teu servo, e a oração de teus servos, que desejam temer o teu nome; e, por favor, faze ter sucesso hoje a teu servo, e dá-lhe favor diante deste homem!Pois eu era copeiro do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 1, 'Sucedeu, pois, no mês de Nisã, no ano vigésimo do rei Artaxerxes, que havendo vinho diante dele, tomei o vinho, e [o] dei ao rei. Porém eu nunca havia estado triste diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 2, 'Por isso o rei me perguntou: Por que o teu rosto está triste, mesmo não estando doente? Isto não pode ser outra coisa, senão tristeza de coração. Tive então muito medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 3, 'E disse ao rei: Viva o rei para sempre! Como meu rosto não estaria triste, quando a cidade, o lugar dos sepulcros de meus pais, está arruinada, e suas portas consumidas a fogo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 4, 'E o rei me disse: O que pedes? Então orei ao Deus dos céus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 5, 'E respondei ao rei: Se for do agrado do rei, e se teu servo é agradável diante de ti, [peço] que me envies a Judá, à cidade dos sepulcros de meus pais, para reconstruí-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 6, 'Então o rei me disse (enquanto a rainha estava sentada junto a ele): Por quanto tempo durará tua viagem, e quando voltarás? E agradou ao rei me enviar, depois que eu lhe defini um certo tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 7, 'Disse mais ao rei: Se for do agrado do rei, sejam dadas a mim cartas para os governadores dalém do rio, para que me permitam passar em segurança até que eu chegue a Judá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 8, 'Como também um carta para Asafe, guarda do jardim do rei, para que me dê madeira para consertar as portas da fortaleza do templo, para o muro da cidade, e para a casa onde entrarei.E o rei me concedeu, segundo a boa mão do SENHOR sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 9, 'Então vim aos governadores dalém do rio, e lhes dei as cartas do rei. E o rei enviou comigo capitães do exército e cavaleiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 10, 'Quando então Sambalate, o horonita, e Tobias, o servo amonita, ouviram, desagradou-lhes muito que alguém viesse para buscar o bem aos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 11, 'Cheguei, pois, a Jerusalém, e fiquei ali três dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 12, 'E de noite me levantei, eu e uns poucos homens comigo, e não declarei a ninguém o que Deus tinha posto em meu coração que fizesse em Jerusalém; e animal nenhum estava comigo, a não ser o o em que eu cavalgava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 13, 'E de noite saí pela porta do Vale até a fonte do Dragão e à porta do Esterco; e observei os muros de Jerusalém que estavam fendidos, e suas portas estavam consumidas a fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 14, 'E passei à porta da Fonte, e ao tanque do rei; e não houve lugar por onde o animal em que eu estava montado pudesse passar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 15, 'Então de noite subi pelo vale, e observei o muro; então voltei, e entrei pela porta do Vale, e assim me retornei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 16, 'E os oficiais não sabiam aonde eu tinha ido, nem o que tinha feito; nem mesmo aos judeus e aos sacerdotes, nem aos nobres e oficiais, nem aos demais que faziam a obra, havia eu declarado coisa alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 17, 'Então eu lhes disse: Com certeza vedes a miséria em que estamos, que Jerusalém está arruinada, e suas portas queimadas a fogo. Vinde, e reconstruamos o muro de Jerusalém, e não sejamos mais humilhados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 18, 'Então lhes declarei como a mão de meu Deus havia sido boa sobre mim, e também as palavras do rei, que ele tinha me dito. Então disseram: Levantemo-nos, e edifiquemos. Assim esforçaram suas mãos para uma boa obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 19, 'Porém, quando Sambalate o horonita, Tobias o servo amonita, e Gesém o árabe, ouviram [isto] ,zombaram de nós, e nos desprezaram, dizendo: O que é isto que vós fazeis? Por acaso estais vos rebelando contra o rei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 2, 20, 'Então lhes respondi, dizendo-lhes: O Deus dos céus é quem nos dará sucesso; e nós, servos dele, nos levantaremos e edificaremos; pois vós não tendes parte, nem direito, nem memória em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 1, 'E Eliasibe, o sumo sacerdote, levantou-se com seus irmãos os sacerdotes, e edificaram a porta das Ovelhas. Eles a consagraram, e levantaram suas portas; eles a consagraram até a torre de Meá, e até a torre de Hananel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 2, 'E ao lado dela os homens de Jericó edificaram; e ao seu lado edificou Zacur, filho de Inri.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 3, 'E os filhos de Hassenaá edificaram a porta do Peixe; puseram-lhe vigas, e levantaram suas portas com suas fechaduras e seus ferrolhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 4, 'E ao seu lado reparou Meremote filho de Urias, filho de Coz; e ao seu lado reparou Mesulão filho de Berequias, filho de Mesezabel; e ao seu lado reparou Zadoque filho de Baaná.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 5, 'E ao seu lado os tecoítas repararam; porém os seus mais ilustres se recusaram a prestar serviço a seu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 6, 'E a porta Velha Joiada filho de Paseia, e Mesulão filho de Besodias repararam; puseram-lhe vigas, e levantaram suas portas com suas fechaduras e seus ferrolhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 7, 'E ao seu lado repararam Melatias o gibeonita, e Jadom meronotita, homens de Gibeom e de Mispá, que está sob o domínio do governador dalém do rio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 8, 'E ao seu lado reparou Uziel filho de Haraías, um dos ourives; e ao seu lado reparou Hananias, um dos perfumistas. Assim restauraram a Jerusalém até o muro largo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 9, 'E ao seu lado reparou Refaías filho de Hur, líder da metade da região de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 10, 'E ao seu lado reparou Jedaías filho de Harumafe, assim como em frente de sua casa; e ao seu lado reparou Hatus filho de Hasbaneias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 11, 'Malquias filho de Harim, e Hassube filho de Paate-Moabe, repararam a outra medida, como também a torre dos Fornos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 12, 'E ao seu lado reparou Salum filho de Haloés, líder da metade da região de Jerusalém; ele e suas filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 13, 'Hanum e os moradores de Zanoa repararam a porta do Vale. Estes a edificaram, levantaram suas portas [com] suas fechaduras e seus ferrolhos, como também mil côvados no muro, até a porta do Esterco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 14, 'Malquias filho de Recabe, líder da região de Bete-Haquerém, reparou a porta do Esterco; ele a edificou, levantou suas portas [com] suas fechaduras e seus ferrolhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 15, 'Salum filho de Col-Hozé, líder da região de Mispá, reparou a porta da Fonte; ele a edificou, a cobriu, e levantou suas portas [com] suas fechaduras e seus ferrolhos; como também o muro do tanque de Selá junto ao jardim do rei, e até as degraus que descem da cidade de Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 16, 'Depois dele reparou Neemias filho de Azbuque, líder de metade da região de Bete-Zur, até em frente dos sepulcros de Davi, e até o tanque artificial, e até a casa dos Guerreiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 17, 'Depois dele repararam os levitas, Reum filho de Bani; ao seu lado reparou Hasabias, líder de metade da região de Queila, em sua região.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 18, 'Depois dele repararam seus irmãos, Bavai filho de Henadade, líder de metade da região de Queila.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 19, 'Ao seu lado reparou Ezer filho de Jesua, líder de Mispá, outra medida; em frente da subida à casa de armas da esquina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 20, 'Depois dele reparou com grande fervor Baruque filho de Zabai a outra medida; desde a esquina até a porta da casa de Eliasibe, o sumo sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 21, 'Depois dele reparou Meremote filho de Urias filho de Coz a outra medida, desde a entrada da casa de Eliasibe, até o fim da casa de Eliasibe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 22, 'E depois dele repararam os sacerdotes, os que habitavam na vizinhança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 23, 'Depois deles repararam Benjamim e Hassube, em frente da casa deles; e depois deles reparou Azarias, filho de Maaseias, filho de Ananias, perto de sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 24, 'Depois dele reparou Binui filho de Henadade, outra medida; desde a casa de Azarias até a esquina, e até o canto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 25, 'Palal, filho de Uzai, em frente da esquina e a torre que sai da casa superior do rei, que está junto ao pátio da prisão. Depois dele, Pedaías filho de Parós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 26, 'E os servos do templo, que habitavam em Ofel, [repararam] até em frente da porta das Águas ao oriente, e à torre alta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 27, 'Depois os tecoítas repararam outra medida; em frente da torre grande [e] alta, até o muro de Ofel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 28, 'Os sacerdotes repararam desde a porta dos Cavalos, cada um em frente de sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 29, 'Depois deles reparou Zadoque filho de Imer, em frente de sua casa; e depois dele reparou Semaías filho de Secanias, guarda da porta oriental.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 30, 'Depois dele reparou Hananias filho de Selemias, e Hanum, o sexto filho de Zalafe, outra medida. Depois dele reparou Mesulão, filho de Berequias, em frente de sua câmara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 31, 'Depois dele reparou Malquias um dos ourives, até a casa dos servos do templo e dos mercadores; em frente da porta da Inspeção, e até a câmara do canto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 3, 32, 'E entre a câmara do canto até a porta das Ovelhas, os ourives e os mercadores repararam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 1, 'E foi que, quando Sambalate ouviu que nós edificávamos o muro, ele se indignou muito, e escarneceu dos judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 2, 'E falou diante de seus irmãos e do exército de Samaria, dizendo: O que fazem estes fracos judeus? Será isso lhes permitido? Farão eles sacrifícios? Acabarão isso algum dia? Ressuscitarão dos amontoados de entulho as pedras que foram queimadas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 3, 'E com ele estava Tobias, o amonita, que disse: Ainda que edifiquem, contudo, se uma raposa vier, ela [sozinha] será capaz de derrubar seu muro de pedra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 4, 'Ouve, ó Deus nosso, que somos desprezados, e devolve a humilhação deles sobre suas cabeças; e entrega-os para o despojo, na terra do cativeiro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 5, 'E não cubras a perversidade deles, nem o pecado deles seja riscado diante de teu rosto; pois provocaram à ira diante dos construtores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 6, 'Edificamos, pois o muro, e todo o muro foi completado até metade [de] sua [altura] ; porque o coração do povo estava disposto a trabalhar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 7, 'E foi que, quando Sambalate e Tobias, e os árabes, os amonitas, e os de Asdode, ouviram que os muros de Jerusalém estavam sendo reparados, que as brechas já começavam a serem fechadas, eles ficaram muito irados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 8, 'E todos conspiraram entre si para virem guerrear contra Jerusalém, e causarem confusão nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 9, 'Porém nós oramos a nosso Deus; e pusemos guarda contra eles, dia e noite, por causa deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 10, 'Então Judá disse: As forças dos carregadores se enfraqueceram, e o entulho é muito; e nós não podemos reconstruir o muro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 11, 'Porém nossos inimigos diziam: Eles não saibam, nem vejam, até que entremos em meio deles, e os matemos; assim faremos cessar a obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 12, 'E foi que, quando os judeus que habitavam entre eles vieram, dez vezes nos disseram: Por todos os lados para que virardes, [eles estão] contra nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 13, 'Então pus [guardas] nos lugares baixos, atrás do muro, [e] nos lugares altos; e pus ao povo por [suas] famílias com suas espadas, suas lanças, e seus arcos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 14, 'Depois olhei, me levantei, e disse aos nobres, aos oficiais, e aos demais do povo: Não os temais; lembrai-vos do Senhor grande e temível, e lutai por vossos irmãos, por vossos filhos e vossas filhas, por vossas mulheres e vossas casas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 15, 'E foi que, quando nossos inimigos ouviram falar que já sabíamos [de tudo] ,e que Deus havia frustrado o plano deles, todos voltamos ao muro, cada um à sua obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 16, 'Sucedeu, porém, que desde aquele dia a metade dos meus servos trabalhava na obra, e outra metade deles tinha lanças, escudos, arcos, e couraças; e os líderes estavam por detrás de toda a casa de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 17, 'Os que edificavam o muro, e os que traziam as cargas [e] os que carregavam, com uma mão faziam a obra, e na outra tinham armas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 18, 'E cada um dos construtores trazia sua espada cingida a seus lombos, e [assim] edificavam; e o que tocava a trombeta estava junto a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 19, 'E eu disse aos nobres, aos oficiais, e aos demais do povo: A obra é grande e extensa, e nós estamos separados no muro, longe uns dos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 20, 'No lugar onde ouvirdes o som da trombeta, ali vos ajuntareis conosco; nosso Deus lutará por nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 21, 'Assim trabalhávamos na obra; e a metade deles tinham lanças desde a subida do amanhecer até o surgir das estrelas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 22, 'Também naquele tempo eu disse ao povo: Cada um passe a noite com seu servo dentro de Jerusalém, para que de noite nos sirvam de guarda, e de dia na obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 4, 23, 'E nem eu, nem meus irmãos, nem meus servos, nem os homens da guarda que me seguiam, nos despíamos de nossas roupas; cada um [mantinha] sua arma [até para] a água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 1, 'Então houve um grande clamor do povo e de suas mulheres contra seus irmãos, os judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 2, 'Pois havia quem dizia: Nós, nossos filhos e nossas filhas, somos muitos; por isso tomamos trigo, para que comamos e vivamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 3, 'Também havia quem dizia: Colocamos em penhor nossas terras, nossas vinhas, e nossas casas, para comprarmos trigo durante a fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 4, 'E havia quem dizia: Pedimos emprestado até para o tributo do rei [sobre] nossas terras e nossas vinhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 5, 'Agora, pois, nossa carne é como a carne de nossos irmãos, [e] nossos filhos como seus filhos; porém eis que nós sujeitamos nossos filhos e nossas filhas por servos, e até [algumas] de nossas filhas estão subjugadas, que não estão em poder de nossas mãos, e outros têm para si nossas terras e nossas vinhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 6, 'Quando eu ouvi seu clamor, fiquei muito irado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 7, 'Então eu meditei em meu coração, e depois briguei com os nobres e com os oficiais, dizendo-lhes: Emprestais com juros cada um a seu irmão?E convoquei contra eles uma grande reunião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 8, 'E disse-lhes: Nós resgatamos nossos irmãos judeus que haviam sido vendidos às nações, conforme o que nos era possível, e vós novamente venderíeis a vossos irmãos, ou seriam eles vendidos a nós? E ficaram calados, e não acharam o que responder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 9, 'E eu disse mais: Não é bom o que fazeis. Por acaso não andareis no temor a nosso Deus, para que não haja humilhação da parte das nações [que são] nossas inimigas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 10, 'Também eu, meus irmãos, e meus servos, temos lhes emprestado a juros dinheiro e grão. Abandonemos esta cobrança de juros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 11, 'Devolvei a eles hoje mesmo suas terras, suas vinhas, seus olivais, e suas casas; e a centésima parte do dinheiro e do trigo, do vinho e do azeite que exigis deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 12, 'Então disseram: Devolveremos, e nada lhes exigiremos; faremos assim como tu dizes. Então chamei aos sacerdotes, e lhes fiz jurar que fariam conforme esta promessa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 13, 'Também sacudi minha roupa, e disse: Assim sacuda Deus de sua casa e de seu trabalho a todo homem que não cumprir esta promessa; e assim seja sacudido e esvaziado. E toda a congregação: Amém! E louvaram ao SENHOR. E o povo fez conforme esta promessa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 14, 'Também desde o dia que fui nomeado governador deles na terra de Judá, desde o ano vinte até o ano trinta e dois do rei Artaxerxes, doze anos, nem eu nem meus irmãos comemos o pão do governador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 15, 'Mas os primeiros governadores que foram antes de mim, oprimiram ao povo, e tomaram deles pão e pelo vinho, além de quarenta siclos de prata; ainda mais, seus servos dominavam opressivamente sobre o povo; porém eu não fiz assim, por causa do temor a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 16, 'Além disso, concentrei meus esforços na obra deste muro, e não compramos terra alguma; e todos meus servos se ajuntaram ali para a obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 17, 'Também cento e cinquenta homens dos judeus, dos oficiais, e dos que vinha até nós dentre as ns nações que estão ao nosso redor, se punham à minha mesa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 18, 'E o que se preparava para cada dia era um boi, [e] seis ovelhas escolhidas; também preparavam aves para mim, e cada dez dias todas as variedades de muito vinho; e nem por isso exigi o pão do governador, porque a servidão deste povo era grave.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 5, 19, 'Lembra-te de mim para o bem, ó meu Deus; [e de] tudo o que fiz a este povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 1, 'Sucedeu, pois, que, quando Sambalate, Tobias, e Gesém o árabe, e os demais de nossos inimigos, ouviram que eu tinha edificado o muro, e que não havia mais brecha nele (ainda que até aquele tempo não tinha posto as portas nas entradas),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 2, 'Sambalate e Gesém mandaram dizer: Vem, e nos reunamos em alguma das aldeias no vale de Ono. Mas eles haviam pensado em fazer o mal a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 3, 'E enviei-lhes mensageiros, dizendo: Eu faço uma grande obra, por isso não posso descer; porque eu pararia a obra, para a deixar, e ir me encontrar convosco?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 4, 'E mandaram a mesma mensagem a mim quatro vezes, e eu lhes respondi da mesma maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 5, 'Então Sambalate enviou a mim seu servo pela quinta vez, com uma carta aberta em sua mão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 6, 'Em que estava escrito: Ouve-se falar entre as nações, e Gesém disse, que tu e os judeus pensais vos rebelar; e por isso tu edificas o muro, para que tu sejas o rei deles, conforme o que se diz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 7, 'E que puseste profetas para proclamem de ti em Jerusalém, dizendo: [Este é] o rei em Judá! Assim o rei ouvirá conforme estas palavras. Vem, pois, agora, e nos reunamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 8, 'Porém eu mandei lhes dizer: Nada do que dizes aconteceu, mas sim és tu que inventas de tua própria mente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 9, 'Porque todos eles procuravam nos atemorizar, dizendo: As mãos deles se enfraquecerão da obra, e ela não será feita.Esforça pois minhas mãos, [ó Deus] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 10, 'E quando eu vim à casa de Semaías filho de Delaías, filho de Meetabel (que estava encerrado), ele me disse: Vamos juntos à casa de Deus dentro do templo, e cerremos as portas do templo, porque virão para te matar; sim, de noite virão para te matar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 11, 'Porém eu disse: Um homem como eu fugiria? E poderia alguém como eu entrar no templo para preservar sua vida? De maneira nenhuma entrarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 12, 'E percebi, e vi que Deus não tinha o enviado, mas sim que ele falou aquela profecia contra mim, porque Tobias e Sambalate haviam lhe subornado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 13, 'Para isto ele foi subornado, para me atemorizar, a fim de que assim eu fizesse, e pecasse; para que tivessem alguma coisa para falarem mal de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 14, 'Lembra-te, meu Deus, de Tobias e de Sambalate, conforme estas suas obras, e também da profetiza Noadia, e dos outros profetas que procuravam me atemorizar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 15, 'O muro foi terminado ao [dia] vinte e cinco do mês de Elul, em cinquenta e dois dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 16, 'E foi que, quando todos os nossos inimigos ouviram, todas as nações ao nosso redor temeram, e abateram-se muito em seus olhos, porque reconheceram que foi nosso Deus que fizera esta obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 17, 'Também naqueles dias muitas foram escritas de [alguns] dos nobres de Judá a Tobias, e as de Tobias vinham a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 18, 'Porque muitos em Judá haviam feito juramento com ele, porque ele era genro de Secanias, filho de Ara; e seu filho Joanã havia tomado a filha de Mesulão, filho de Berequias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 6, 19, 'Também contavam diante de mim suas boas obras, e levavam a ele minhas palavras. E Tobias me enviava cartas para me atemorizar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 1, 'Sucedeu, pois, que, quando o muro já havia sido edificado, e já tinha posto as portas, e sido estabelecidos os porteiros, os cantores e os Levitas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 2, 'Mandei o meu irmão Hanani, e Hananias, chefe do palácio de Jerusalém (porque era um homem fiel e temente a Deus, mais que muitos),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 3, 'E disse-lhes: Não se abram as portas de Jerusalém até que o sol aqueça; e enquanto ainda estiverem presentes, fechem as portas, e [as] trancai. E ponham-se guardas dos moradores de Jerusalém, cada um em sua guarda, e cada um diante de sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 4, 'E a cidade era espaçosa e grande, porém pouca gente havia dentro dela, e as casas [ainda] não haviam sido reconstruídas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 5, 'Então Deus pôs em meu coração que juntasse os nobres, os oficiais, e o povo, para que fossem registrados pela ordem de suas genealogias; e achei o livro da genealogia dos que haviam subido antes, e achei nele escrito [o seguinte] :'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 6, 'Estes são os filhos da província que subiram do cativeiro, dos que foram levados por Nabucodonosor, rei de Babilônia, e que voltaram a Jerusalém e a Judá, cada um à sua cidade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 7, 'Os quais vieram com Zorobabel, Jesua, Neemias, Azarias, Raamias, Naamani, Mardoqueu, Bilsã, Misperete, Bigvai, Neum, Baaná. Este é o número dos homens do povo de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 8, 'Os filhos de Parós, dois mil cento e setenta e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 9, 'Os filhos de Sefatias, trezentos e setenta e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 10, 'Os filhos de Ara, seiscentos e cinquenta e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 11, 'Os filhos de Paate-Moabe, dos filhos de Jesua e de Joabe, dois mil oitocentos e dezoito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 12, 'Os filhos de Elão, mil duzentos e cinquenta e quatro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 13, 'Os filhos de Zatu, oitocentos e quarenta e cinco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 14, 'Os filhos de Zacai, setecentos e sessenta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 15, 'Os filhos de Binui, seiscentos e quarenta e oito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 16, 'Os filhos de Bebai, seiscentos e vinte e oito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 17, 'Os filhos de Azgade, dois mil seiscentos e vinte e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 18, 'Os filhos de Adonicão, seiscentos e sessenta e sete;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 19, 'Os filhos de Bigvai, dois mil e sessenta e sete;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 20, 'Os filhos de Adim, seiscentos e cinquenta e cinco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 21, 'Os filhos de Ater, de Ezequias, noventa e oito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 22, 'Os filhos de Hasum, trezentos e vinte e oito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 23, 'Os filhos de Bezai, trezentos e vinte e quatro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 24, 'Os filhos de Harife, cento e doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 25, 'Os filhos de Gibeom, noventa e cinco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 26, 'Os homens de Belém e de Netofá, cento e oitenta e oito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 27, 'Os homens de Anatote, cento e vinte e oito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 28, 'Os homens de Bete-Azmavete, quarenta e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 29, 'Os homens de Quiriate-Jearim, Cefira e Beerote, setecentos e quarenta e três;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 30, 'Os homens de Ramá e de Geba, seiscentos e vinte e um;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 31, 'Os homens de Micmás, cento e vinte e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 32, 'Os homens de Betel e de Ai, cento e vinte e três;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 33, 'Os homens da outra Nebo, cinquenta e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 34, 'Os filhos do outro Elão, mil duzentos e cinquenta e quatro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 35, 'Os filhos de Harim, trezentos e vinte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 36, 'Os filhos de Jericó, trezentos e quarenta e cinco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 37, 'Os filhos de Lode, de Hadide, e Ono, setecentos vinte e um;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 38, 'Os filhos de Senaá, três mil novecentos e trinta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 39, 'Os sacerdotes: os filhos de Jedaías, da casa de Jesua, novecentos e setenta e três;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 40, 'Os filhos de Imer, mil e cinquenta e dois;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 41, 'Os filhos de Pasur, mil duzentos quarenta e sete;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 42, 'Os filhos de Harim, mil dez e sete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 43, 'Os levitas: os filhos de Jesua, de Cadmiel, dos filhos de Hodeva, setenta e quatro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 44, 'Os cantores: os filhos de Asafe, cento e quarenta e oito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 45, 'Os porteiros: os filhos de Salum, os filhos de Ater, os filhos de Talmom, os filhos de Acube, os filhos de Hatita, os filhos de Sobai, cento e trinta e oito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 46, 'Os servos do templo: os filhos de Zia, os filhos de Hasufa, os filhos de Tabaote,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 47, 'Os filhos de Queros, os filhos de Sia, os filhos de Padom,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 48, 'Os filhos de Lebana, os filhos de Hagaba, os filhos de Salmai,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 49, 'Os filhos de Hanã, os filhos de Gidel, os filhos de Gaar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 50, 'Os filhos de Reaías, os filhos de Rezim, os filhos de Necoda,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 51, 'Os filhos de Gazão, os filhos de Uzá, os filhos de Paseia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 52, 'Os filhos de Besai, os filhos de Meunim, os filhos de Nefusesim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 53, 'Os filhos de Baquebuque, os filhos de Hacufa, os filhos de Harur,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 54, 'Os filhos de Baslite, os filhos de Meída, os filhos de Harsa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 55, 'Os filhos de Barcos, os filhos de Sísera, os filhos de Tamá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 56, 'Os filhos de Nesias, os filhos de Hatifa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 57, 'Os filhos dos servos de Salomão: os filhos de Sotai, os filhos de Soferete, os filhos de Perida,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 58, 'Os filhos de Jaala, os filhos de Darcom, os filhos de Gidel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 59, 'Os filhos de Sefatias, os filhos de Hatil, os filhos de Poquerete-Hazebaim, os filhos de Amom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 60, 'Todos os servos do templo, e filhos dos servos de Salomão, trezentos e noventa e dois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 61, 'Também estes subiram de Tel-Melá, Tel-Harsa, Querube, Adom, e Imer, porém não puderam mostrar a casa de seus pais, nem sua linhagem, se eram de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 62, 'Os filhos de Delaías, os filhos de Tobias, os filhos de Necoda, seiscentos e quarenta e dois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 63, 'E dos sacerdotes: os filhos de Habaías, os filhos de Coz, os filhos de Barzilai, o qual tomara mulher das filhas de Barzilai, o gileadita, e chamou-se pelo nome delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 64, 'Estes buscaram seu registro de genealogias, porém não se achou; por isso, como impuros, foram excluídos do sacerdócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 65, 'E o governador lhes disse que não comessem das coisas mais santas, até que houvesse sacerdote com Urim e Tumim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 66, 'Toda esta congregação junta era quarenta e dois mil trezentos e sessenta,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 67, 'Exceto seus servos e suas servas, que eram sete mil trezentos e trinta e sete; e tinham duzentos e quarenta e cinco cantores e cantoras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 68, 'Seus cavalos, setecentos e trinta e seis; seus mulos, duzentos e quarenta e cinco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 69, 'Os camelos, quatrocentos e trinta e cinco; asnos, seis mil setecentos e vinte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 70, 'E alguns dos chefes das famílias fizeram doações para a obra. O governador deu para o tesouro mil dracmas de ouro, cinquenta bacias, e quinhentas trinta vestes sacerdotais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 71, 'E [alguns] dos chefes das famílias deram para o tesouro da obra, vinte mil dracmas de ouro, e duas mil e duzentas libras de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 72, 'E o que o resto do povo deu foi vinte mil dracmas de ouro, duas mil libras de prata, e sessenta e sete vestes sacerdotais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 7, 73, 'E os sacerdotes, os Levitas, e os porteiros, os cantores, os do povo, os servos do templo, e todo Israel, habitaram em suas cidades.E vindo o mês sétimo, estando os filhos de Israel em suas cidades,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 1, 'E todo o povo se juntou como um só homem na praça diante da porta das Águas, e disseram ao escriba Esdras que trouxesse o livro da lei de Moisés, que o SENHOR havia mandado a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 2, 'E Esdras, o sacerdote, trouxe a lei diante da congregação, tanto de homens como de mulheres, e de todos os que tivessem entendimento para ouvir, no primeiro dia do sétimo mês.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 3, 'E leu no [livro] diante da praça que está diante da porta das Águas, desde o amanhecer até o meio-dia, na presença de homens, mulheres e entendidos; e os ouvidos de todo o povo estavam [atentos] ao livro da lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 4, 'E o escriba Esdras estava sobre uma plataforma de madeira, que haviam feito para aquilo; e junto a ele estavam Matitias, Sema, Anaías, Urias, Hilquias, e Maaseias, à sua direita; e a sua esquerda, Pedaías, Misael, Malquias, Hasum, Hasbadana, Zacarias, e Mesulão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 5, 'E Esdras abriu o livro perante os olhos de todo o povo, porque estava mais alto que todo o povo; e quando ele o abriu, todo o povo se pôs de pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 16, 'Neemias', 'Ne', 8, 6, 'Então Esdras louvou ao SENHOR, o grande Deus. E todo o povo respondeu: Amém! Amém! levantando suas mãos; e inclinaram-se, e adoraram ao SENHOR com os rostos em terra.')
